(()=>{'use strict';const $=id=>document.getElementById(id),R=FieldtripRoutes,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>new Date(s).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles'}),date=s=>new Date(s+'T12:00:00-07:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Los_Angeles'});let result=null;
$('route-days').innerHTML=LA_DATA.days.map((d,i)=>`<label><input type="radio" name="route-days" value="${d}" ${i===0?'checked':''}> ${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]} ${12+i}</label>`).join('');
$('route-area').innerHTML='<option value="">Any municipality or place</option>'+BrowseCore.placeGroups(LA_DATA.events).map(g=>`<optgroup label="${esc(g.label)}">${g.options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</optgroup>`).join('');
const hours=id=>{const v=$(id).value;if(v.includes(':')){const [h,m]=v.split(':').map(Number);return h+m/60;}return Number(v);};
function options(){return {requireAccess:$('require-access').checked,days:[...document.querySelectorAll('[name="route-days"]:checked')].map(e=>e.value),goal:$('route-goal').value,municipality:$('route-area').value,from:hours('route-from'),to:hours('route-to'),buffer:$('route-buffer').value};}
function render(){const o=options();result=R.search(Fieldtrip.routePool?Fieldtrip.routePool(o):LA_DATA.events,o);$('route-summary').textContent=`${result.eligible} eligible events · ${result.routes.length?result.routes.length+' routes':result.reason}`;$('route-results').innerHTML=result.routes.map((p,i)=>`<article class="route-card"><div class="route-top"><span>OPTION 0${i+1}</span><span>${p.events.length} ${p.events.length===1?'EVENT':'EVENTS'}</span></div><h3>${esc(date(p.day))}</h3><p class="route-time">${time(p.start)} — ${time(p.end)} PT<br>${esc(p.area)}</p><ol>${p.events.map((e,j)=>`<li><span class="route-clock">${time(e.startsAt)}—${time(e.endsAt)}</span><button data-route-detail="${esc(e.id)}">${esc(e.name)}</button><p>${esc(BrowseCore.label(e))} · ${esc(R.signals(e,o.goal).join(' · ')||e.formats[0]||'Event')}</p>${j?`<small>${Math.round((Date.parse(e.startsAt)-Date.parse(p.events[j-1].endsAt))/60000)} minutes after the previous event</small>`:''}${e.access==='APPLY'?'<small> · Application required</small>':''}</li>`).join('')}</ol><div class="route-proof">${p.matched} ${p.matched===1?'event matches':'events match'} your goal<br>${p.buffer==='flexible'?'Flexible spacing by location':p.buffer+' minute minimum gap'}. Confirm venues and travel.</div><button class="route-save" data-route-save="${i}">Add this day ↗</button></article>`).join('');$('route-results').hidden=!result.routes.length;}
$('route-form').onsubmit=e=>{e.preventDefault();render();};$('route-open').onclick=()=>{const state=Fieldtrip.getState(),day=state.day||state.days?.[0]||LA_DATA.days[0];document.querySelectorAll('[name="route-days"]').forEach(c=>c.checked=c.value===day);const place=$('municipality')||$('place-filter');if(place)$('route-area').value=place.value;const studio=$('route-studio');studio.hidden=false;if(studio.showModal&&!studio.open)studio.showModal();render();if(!studio.showModal)studio.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('route-goal').focus({preventScroll:true});};$('route-close').onclick=()=>{const studio=$('route-studio');if(studio.close)studio.close();studio.hidden=true;$('route-open').focus();};
$('route-results').onclick=e=>{const d=e.target.closest('[data-route-detail]');if(d)Fieldtrip.open(d.dataset.routeDetail);const s=e.target.closest('[data-route-save]');if(s&&result){Fieldtrip.add(result.routes[Number(s.dataset.routeSave)].events.map(e=>e.id));s.textContent='Added to your week ✓';}};
$('share-plan').onclick=async()=>{const ids=Fieldtrip.getState().saved;if(!ids.length)return;const share=new URL(location.href);share.hash='plan='+encodeURIComponent(ids.join(','));try{await navigator.clipboard.writeText(share.href);$('share-feedback').textContent='Link copied. It includes selected public event IDs only.';}catch{$('share-feedback').textContent='Copy this link:';$('share-link').hidden=false;$('share-link').value=share.href;$('share-link').select();}};
if(location.hash.startsWith('#plan=')){try{const known=new Set(LA_DATA.events.map(e=>e.id)),ids=[...new Set(decodeURIComponent(location.hash.slice(6)).split(',').filter(id=>known.has(id)))];if(ids.length){$('shared-preview').hidden=false;$('shared-preview-text').textContent=`A shared week with ${ids.length} events.`;$('shared-add').onclick=()=>{Fieldtrip.add(ids);$('shared-preview').hidden=true;history.replaceState(null,'',location.pathname+location.search);};}}catch{}}
})();
